'use strict';

/*
  Research Frontend Module
  - โมดูลผลงานวิจัยของบุคลากร
  - แสดงรายการวิจัย กรอง/ค้นหา และแก้ไขข้อมูลที่ผูกกับ person_code
  - ระวัง field ปี: year_ce และ year_be ต้องไม่สลับความหมาย
*/

const RESEARCH_CONFIG = {
  API_URL: (window.MIS_CONFIG && window.MIS_CONFIG.API_URL) || 'https://script.google.com/macros/s/AKfycbxe1NQ1APDCMdhrp9f7f_TEGYWS4GkCmLnCS87ARFePJDA9WG-Td_8nPQ9r6SNOgr6wdg/exec'
};

let researchRows = [];
let visibleResearchRows = [];

function getResearchYearBe(row) {
  const yearBe = Number(row && row.YEAR_BE);
  if (Number.isFinite(yearBe) && yearBe > 0) return String(yearBe);
  const yearCe = Number(row && row.YEAR_CE);
  if (Number.isFinite(yearCe) && yearCe > 0) return String(yearCe > 2400 ? yearCe : yearCe + 543);
  return '';
}

function normalizeResearch(row) {
  row = normalizeRecord(row || {});
  return {
    ...row,
    ROW_INDEX: row.ROW_INDEX || row.rowIndex || '',
    RESEARCH_ID: row.RESEARCH_ID || row.KEY_ID || row.researchId || '',
    TITLE: row.TITLE || row.Title || row['ชื่อเรื่อง'] || row['ชื่อแผนงาน'] || '',
    JOURNAL: row.JOURNAL || row['วารสาร'] || '',
    YEAR_CE: row.YEAR_CE || row['YEAR ค.ศ'] || row.YEAR || '',
    YEAR_BE: row.YEAR_BE || row['ปี พ.ศ.'] || '',
    TYPE: row.TYPE || row['ประเภท'] || '',
    RESEARCH_STATUS: row.RESEARCH_STATUS || row['สถานะ'] || '',
    PUBLISH_STATUS: row.PUBLISH_STATUS || row['ตีพิมพ์'] || '',
    AUTHOR_LEVEL: row.AUTHOR_LEVEL || row.Level || '',
    FUND_STATUS: row.FUND_STATUS || row['ทุน'] || '',
    REF: row.REF || row.ref || row.REFERENCE || row['อ้างอิง'] || '',
    FUND_SOURCE: row.FUND_SOURCE || row['แหล่งทุน'] || '',
    FUND_AMOUNT: row.FUND_AMOUNT || row['จำนวนเงิน'] || '',
    SUBJECT_GROUP: row.SUBJECT_GROUP || row['สาขาวิชา'] || row['กลุ่มวิชา'] || '',
    LINK: row.LINK || row.Link || ''
  };
}

async function researchApi(action, payload = {}) {
  const url = new URL(RESEARCH_CONFIG.API_URL);
  url.searchParams.set('action', action);
  url.searchParams.set('system', 'MIS');

  const user = typeof getActiveMisUser === 'function' ? getActiveMisUser() : (Auth.getUser() || {});
  const body = {
    action,
    system: 'MIS',
    token: Auth.getToken(),
    personId: user.personId || '',
    email: user.email || '',
    fullName: user.fullName || '',
    ...payload
  };

  const response = await fetch(url.toString(), {
    method: 'POST',
    headers: { 'Content-Type': 'text/plain;charset=utf-8' },
    body: JSON.stringify(body)
  });
  const text = await response.text();
  if (!response.ok) {
    return {
      ok: false,
      message: getResearchApiErrorMessage(response.status, text),
      raw: text
    };
  }
  try {
    const result = JSON.parse(text);
    return {
      ...result,
      ok: result.ok === true || result.success === true,
      data: result.data || result.rows || result.items || [],
      message: result.message || ''
    };
  } catch (_) {
    return { ok: false, message: getResearchApiErrorMessage(response.status, text), raw: text };
  }
}

function getResearchApiErrorMessage(status, text) {
  const preview = String(text || '').trim().slice(0, 180);
  if (/^<!doctype html|^<html[\s>]/i.test(preview)) {
    return 'Research API ไม่ได้ส่ง JSON กลับมา กรุณาตรวจสอบ Apps Script deploy/backend URL';
  }
  return preview
    ? `Research API ตอบกลับผิดรูปแบบ (HTTP ${status || 'unknown'}): ${preview}`
    : `Research API ตอบกลับผิดรูปแบบ (HTTP ${status || 'unknown'})`;
}

function setResearchAlert(message, type = 'info') {
  const el = document.getElementById('research-alert');
  if (!el) return;
  el.textContent = message || '';
  el.className = `data-alert data-alert-${type}`;
  el.hidden = !message;
}

async function loadResearch() {
  const panel = document.getElementById('research-panel');
  if (panel) panel.hidden = true;
  setResearchAlert('กำลังโหลดข้อมูลงานวิจัย...', 'info');

  try {
    const result = await researchApi('getMyResearch');
    if (!result.ok) {
      setResearchAlert(result.message || 'โหลดข้อมูลงานวิจัยไม่สำเร็จ', 'error');
      return;
    }

    researchRows = Array.isArray(result.data) ? result.data.map(normalizeResearch) : [];
    renderResearch(researchRows);
    setResearchAlert('', 'info');
    if (panel) panel.hidden = false;
  } catch (err) {
    console.error(err);
    setResearchAlert(err.message || 'เชื่อมต่อ Research API ไม่สำเร็จ', 'error');
  }
}

function renderResearch(rows) {
  visibleResearchRows = Array.isArray(rows) ? [...rows] : [];
  const tbody = document.getElementById('research-tbody');
  const mobile = document.getElementById('research-mobile-cards');
  const total = document.getElementById('research-total-badge');
  if (total) total.textContent = `${visibleResearchRows.length} รายการ`;
  if (!tbody || !mobile) return;

  if (!visibleResearchRows.length) {
    tbody.innerHTML = '<tr><td colspan="8" class="research-empty">ยังไม่มีผลงานวิจัย</td></tr>';
    mobile.innerHTML = '<div class="research-empty-card">ยังไม่มีผลงานวิจัย</div>';
    return;
  }

  tbody.innerHTML = visibleResearchRows.map((row, index) => {
    const key = escapeHtml(row.RESEARCH_ID || '');
    const rowIndex = escapeHtml(row.ROW_INDEX || '');
    const title = displayValue(row.TITLE);
    const yearBe = getResearchYearBe(row);
    const link = row.LINK || '';
    const titleHtml = link
      ? `<a href="${escapeHtml(link)}" target="_blank" rel="noopener">${escapeHtml(title)}</a>`
      : escapeHtml(title);
    return `
      <tr>
        <td>${index + 1}</td>
        <td class="research-title-cell">${titleHtml}</td>
        <td>${escapeHtml(displayValue(row.JOURNAL))}</td>
        <td>${escapeHtml(displayValue(yearBe))}</td>
        <td><span class="research-badge soft">${escapeHtml(displayValue(row.TYPE))}</span></td>
        <td><span class="research-badge ${getResearchStatusClass(row.RESEARCH_STATUS)}">${escapeHtml(displayValue(row.RESEARCH_STATUS))}</span></td>
        <td>${escapeHtml(displayValue(row.FUND_STATUS))}</td>
        <td>
          <div class="research-row-actions">
            <button class="btn btn-secondary btn-small" type="button" data-research-edit="${key}" data-row-index="${rowIndex}">แก้ไข</button>
            <button class="btn btn-danger btn-small" type="button" data-research-delete="${key}" data-row-index="${rowIndex}" data-title="${escapeHtml(title)}">ลบ</button>
          </div>
        </td>
      </tr>
    `;
  }).join('');

  mobile.innerHTML = visibleResearchRows.map((row) => {
    const key = escapeHtml(row.RESEARCH_ID || '');
    const rowIndex = escapeHtml(row.ROW_INDEX || '');
    const yearBe = getResearchYearBe(row);
    return `
      <article class="research-mobile-card">
        <strong>${escapeHtml(displayValue(row.TITLE))}</strong>
        <span>${escapeHtml(displayValue(row.JOURNAL))} / ${escapeHtml(displayValue(yearBe))}</span>
        <div class="research-row-actions">
          <button class="btn btn-secondary btn-small" type="button" data-research-edit="${key}" data-row-index="${rowIndex}">แก้ไข</button>
          <button class="btn btn-danger btn-small" type="button" data-research-delete="${key}" data-row-index="${rowIndex}" data-title="${escapeHtml(displayValue(row.TITLE))}">ลบ</button>
        </div>
      </article>
    `;
  }).join('');
}

function getResearchStatusClass(status) {
  const text = String(status || '');
  if (text.includes('เสร็จ') || text.includes('ตีพิมพ์')) return 'success';
  if (text.includes('กำลัง') || text.includes('ระหว่าง')) return 'warning';
  return 'soft';
}

function filterResearch() {
  const query = (document.getElementById('research-search-input')?.value || '').trim().toLowerCase();
  if (!query) {
    renderResearch(researchRows);
    return;
  }
  renderResearch(researchRows.filter((row) => [
    row.TITLE,
    row.JOURNAL,
    row.YEAR_CE,
    row.YEAR_BE,
    row.TYPE,
    row.RESEARCH_STATUS,
    row.PUBLISH_STATUS,
    row.SUBJECT_GROUP,
    row.REF
  ].join(' ').toLowerCase().includes(query)));
}

function openResearchModal(row) {
  const form = document.getElementById('research-form');
  if (!form) return;
  form.reset();
  setResearchFormAlert('');
  document.getElementById('research-form-key-id').value = '';
  document.getElementById('research-form-row-index').value = '';

  if (row) {
    document.getElementById('research-modal-title').textContent = 'แก้ไขผลงานวิจัย';
    populateResearchForm(form, row);
    document.getElementById('research-form-key-id').value = row.RESEARCH_ID || '';
    document.getElementById('research-form-row-index').value = row.ROW_INDEX || '';
  } else {
    document.getElementById('research-modal-title').textContent = 'เพิ่มผลงานวิจัย';
    document.getElementById('publish-status').value = 'โครงร่าง';
  }

  syncResearchStatusFromPublishStatus();
  toggleResearchIndexField();
  toggleResearchFundingFields();
  openModal('research-modal');
}

function populateResearchForm(form, row) {
  Array.from(form.elements).forEach((el) => {
    if (!el.name) return;
    const value = row[el.name] || row[normalizeResearchFieldName(el.name)] || '';
    el.value = value;
  });
}

function normalizeResearchFieldName(name) {
  const map = {
    'สาขาวิชา': 'SUBJECT_GROUP',
    'กลุ่มวิชา': 'SUBJECT_GROUP',
    ref: 'REF',
    REFERENCE: 'REF',
    'อ้างอิง': 'REF'
  };
  return map[name] || name;
}

function serializeResearchForm(form) {
  const payload = {};
  Array.from(form.elements).forEach((el) => {
    if (!el.name || el.disabled) return;
    payload[el.name] = el.value;
  });
  if (payload.YEAR_BE && !payload.YEAR_CE) payload.YEAR_CE = String(Number(payload.YEAR_BE) - 543);
  return payload;
}

function setResearchFormAlert(message, type = 'error') {
  const el = document.getElementById('research-form-alert');
  if (!el) return;
  el.textContent = message || '';
  el.className = `data-alert data-alert-${type}`;
  el.hidden = !message;
}

function syncResearchStatusFromPublishStatus() {
  const publishStatus = String(document.getElementById('publish-status')?.value || '').trim();
  const nextStatus = isResearchCompletedStatus(publishStatus)
    ? 'ดำเนินการเสร็จสิ้น'
    : 'กำลังดำเนินการ';
  setInputValue('research-status-input', nextStatus);
  setInputValue('research-status-display', nextStatus);
}

function shouldShowResearchPublicationFields(status) {
  return ['Peer Review', 'Accepted', 'ตีพิมพ์'].includes(String(status || '').trim());
}

function isResearchCompletedStatus(status) {
  return ['Accepted', 'ตีพิมพ์'].includes(String(status || '').trim());
}

function isResearchPublishedStatus(status) {
  return String(status || '').trim() === 'ตีพิมพ์';
}

function toggleResearchIndexField() {
  const publishStatus = String(document.getElementById('publish-status')?.value || '').trim();
  const visible = shouldShowResearchPublicationFields(publishStatus);
  const required = isResearchPublishedStatus(publishStatus);
  ['journal-input', 'year-be-input', 'author-level-input', 'link-input', 'ref-input'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.required = required;
  });
  const section = document.getElementById('research-publication-section');
  if (section) section.style.display = visible ? '' : 'none';
  const indexGroup = document.getElementById('index-status-group');
  if (indexGroup) indexGroup.style.display = visible ? '' : 'none';
  const refGroup = document.getElementById('research-ref-group');
  if (refGroup) refGroup.style.display = visible ? '' : 'none';
  if (!visible) {
    ['journal-input', 'year-be-input', 'author-level-input', 'link-input', 'index-status-input', 'ref-input'].forEach((id) => setInputValue(id, ''));
  }
  if (typeof refreshRequiredFieldLabels === 'function') refreshRequiredFieldLabels(document.getElementById('research-form') || document);
}

function toggleResearchFundingFields() {
  const fundStatus = String(document.getElementById('fund-status')?.value || '').trim();
  const required = fundStatus === 'มี';
  ['fund-source-input', 'fund-amount-input'].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.required = required;
    if (el && !required) el.value = '';
  });
  if (typeof refreshRequiredFieldLabels === 'function') refreshRequiredFieldLabels(document.getElementById('research-form') || document);
}

function validateResearchForm(payload) {
  if (!String(payload.TITLE || '').trim()) return 'กรุณากรอกชื่อเรื่องงานวิจัย';
  if (!String(payload.TYPE || '').trim()) return 'กรุณาเลือกประเภท';
  if (!String(payload.PUBLISH_STATUS || '').trim()) return 'กรุณาเลือกสถานะการตีพิมพ์';
  if (!String(payload['สาขาวิชา'] || payload.SUBJECT_GROUP || '').trim()) return 'กรุณาเลือกกลุ่มวิชา';
  if (!String(payload.FUND_STATUS || '').trim()) return 'กรุณาเลือกทุน';

  const published = isResearchPublishedStatus(payload.PUBLISH_STATUS);
  if (published && !String(payload.JOURNAL || '').trim()) return 'กรุณากรอกวารสาร / Journal';
  if (published && !String(payload.YEAR_BE || '').trim()) return 'กรุณากรอกปี พ.ศ.';
  if (String(payload.YEAR_BE || '').trim()) {
    const yearBe = Number(payload.YEAR_BE);
    if (!Number.isInteger(yearBe) || yearBe < 2400 || yearBe > 2700) return 'ปี พ.ศ. ต้องอยู่ระหว่าง 2400-2700';
  }
  if (published && !String(payload.AUTHOR_LEVEL || '').trim()) return 'กรุณาเลือกบทบาทในงานวิจัย';
  if (published && !String(payload.LINK || '').trim()) return 'กรุณากรอกลิงก์งานวิจัย';
  if (published && !String(payload.ref || '').trim()) return 'กรุณากรอกอ้างอิง (ref)';
  if (payload.FUND_STATUS === 'มี' && !String(payload.FUND_SOURCE || '').trim()) return 'กรุณากรอกแหล่งทุน';
  if (payload.FUND_STATUS === 'มี' && !String(payload.FUND_AMOUNT || '').trim()) return 'กรุณากรอกจำนวนเงิน';
  return '';
}

async function saveResearch(event) {
  event?.preventDefault();
  const form = document.getElementById('research-form');
  const button = document.getElementById('research-save-btn');
  if (!form) return;

  syncResearchStatusFromPublishStatus();
  const payload = serializeResearchForm(form);
  const validation = validateResearchForm(payload);
  if (validation) {
    setResearchFormAlert(validation, 'error');
    return;
  }

  const action = payload.RESEARCH_ID || payload.ROW_INDEX ? 'updateResearch' : 'createResearch';
  setButtonLoading(button, true, 'กำลังบันทึก...');
  setResearchFormAlert('', 'error');

  try {
    const result = await researchApi(action, payload);
    if (!result.ok) {
      setResearchFormAlert(result.message || 'บันทึกข้อมูลงานวิจัยไม่สำเร็จ', 'error');
      return;
    }
    closeModal('research-modal');
    setResearchAlert(result.message || 'บันทึกข้อมูลงานวิจัยเรียบร้อยแล้ว', 'info');
    await loadResearch();
  } catch (err) {
    console.error(err);
    setResearchFormAlert(err.message || 'เชื่อมต่อ Research API ไม่สำเร็จ', 'error');
  } finally {
    setButtonLoading(button, false);
  }
}

async function deleteResearchByKey(key, rowIndex, title) {
  if (!window.confirm(`ต้องการลบ "${title || 'ผลงานวิจัยนี้'}" ใช่หรือไม่?`)) return;
  try {
    const result = await researchApi('deleteResearch', { RESEARCH_ID: key || '', ROW_INDEX: rowIndex || '' });
    if (!result.ok) {
      setResearchAlert(result.message || 'ลบข้อมูลงานวิจัยไม่สำเร็จ', 'error');
      return;
    }
    await loadResearch();
  } catch (err) {
    console.error(err);
    setResearchAlert(err.message || 'เชื่อมต่อ Research API ไม่สำเร็จ', 'error');
  }
}

function exportResearch() {
  const rows = visibleResearchRows.length ? visibleResearchRows : researchRows;
  if (!rows.length) {
    setResearchAlert('ยังไม่มีข้อมูลสำหรับ export', 'error');
    return;
  }
  const win = window.open('', '_blank');
  if (!win) {
    window.print();
    return;
  }
  win.document.write(`
    <html><head><title>รายงานสรุปผลงานวิจัย</title><style>
      body{font-family:Sarabun,Arial,sans-serif;padding:28px;color:#16283d}
      table{width:100%;border-collapse:collapse}th,td{border:1px solid #dbe4f0;padding:8px;text-align:left;vertical-align:top}
      th{background:#f3f7ff}
    </style></head><body>
      <h1>รายงานสรุปผลงานวิจัย</h1>
      <p>จำนวน ${rows.length} รายการ</p>
      <table><thead><tr><th>#</th><th>ชื่อเรื่อง</th><th>วารสาร</th><th>ปี</th><th>สถานะ</th></tr></thead><tbody>
      ${rows.map((row, index) => `<tr><td>${index + 1}</td><td>${escapeHtml(displayValue(row.TITLE))}</td><td>${escapeHtml(displayValue(row.JOURNAL))}</td><td>${escapeHtml(displayValue(getResearchYearBe(row)))}</td><td>${escapeHtml(displayValue(row.RESEARCH_STATUS))}</td></tr>`).join('')}
      </tbody></table>
    </body></html>
  `);
  win.document.close();
  win.print();
}

function initResearchModule() {
  document.getElementById('research-add-btn')?.addEventListener('click', () => openResearchModal(null));
  document.getElementById('research-export-btn')?.addEventListener('click', exportResearch);
  document.getElementById('research-search-input')?.addEventListener('input', filterResearch);
  document.getElementById('research-form')?.addEventListener('submit', saveResearch);
  document.getElementById('publish-status')?.addEventListener('change', () => {
    syncResearchStatusFromPublishStatus();
    toggleResearchIndexField();
  });
  document.getElementById('fund-status')?.addEventListener('change', toggleResearchFundingFields);

  document.addEventListener('click', (event) => {
    const editButton = event.target.closest('[data-research-edit]');
    if (editButton) {
      const key = editButton.getAttribute('data-research-edit') || '';
      const rowIndex = editButton.getAttribute('data-row-index') || '';
      const row = researchRows.find((item) =>
        String(item.RESEARCH_ID || '') === key ||
        String(item.ROW_INDEX || '') === rowIndex
      );
      if (row) openResearchModal(row);
      return;
    }

    const deleteButton = event.target.closest('[data-research-delete]');
    if (deleteButton) {
      deleteResearchByKey(
        deleteButton.getAttribute('data-research-delete') || '',
        deleteButton.getAttribute('data-row-index') || '',
        deleteButton.getAttribute('data-title') || ''
      );
    }
  });
}
